import json
import os

file_path = "storage/progressor/raw_eval_logs/gen_1_eval_437.json"

print(f"Attempting to read file: {file_path}")

if not os.path.exists(file_path):
    print(f"Error: File not found at {file_path}")
else:
    try:
        with open(file_path, 'r') as f:
            content = f.read()
            # Try to load as JSON. It might be a simple string.
            try:
                json_obj = json.loads(content)
                print(f"File content (JSON): {json.dumps(json_obj, indent=2)[:2000]}...") # Print a snippet of parsed JSON
            except json.JSONDecodeError:
                # If it's not JSON, it might be the raw log content as a string
                print(f"File content (Raw String): {content[:2000]}...")

            if "PYTHON SANDBOX EXECUTION:" in content and "action_strategy =" in content:
                print("\nFile content appears to contain raw simulation data with agent strategies. This is the format required.")
            else:
                print("\nFile content does NOT appear to contain raw simulation data or agent strategies in the expected format for direct extraction.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
